rmix <- function(n, p) {
  # 每个样本：以概率 p 从 N(0,1) 抽，以概率 1-p 从 N(3,1) 抽
  k <- rbinom(n, 1, p)         # k=1 选 N(0,1)，k=0 选 N(3,1)
  x <- ifelse(k == 1, rnorm(n, 0, 1), rnorm(n, 3, 1))
  return(x)
}

# 对不同 p 值画密度图
par(mfrow = c(2, 3))           # 2 行 3 列子图
for (p in c(0.1, 0.3, 0.5, 0.7, 0.9)) {
  set.seed(123)
  x <- rmix(1000, p)
  hist(x, breaks = 30, prob = TRUE, main = paste("p =", p))
  # 叠加理论密度
  curve(p * dnorm(x, 0, 1) + (1 - p) * dnorm(x, 3, 1),
        add = TRUE, col = "red", lwd = 2)
}
